import { IngestPipeline, Api } from "@514labs/moose-lib";

// User Activity Event Model
export interface UserActivity {
  event_id: string;
  event_ts: Date;
  user_id: string;
  action: string;
  duration_ms: number;
}

// Ingest Pipeline for User Activity Events
// Optimized for two query patterns:
// 1. Activity counts per user over a date range (user_id, event_ts ordering)
// 2. Total duration per action type (action included in ordering)
export const UserActivityPipeline = new IngestPipeline<UserActivity>(
  "UserActivity",
  {
    table: {
      orderByFields: ["user_id", "event_ts", "action"]
    },
    stream: true,
    ingestApi: true,
  }
);

