#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

async function loadUserActivityData() {
  const csvPath = '/data/samples/user_activity_sample.csv';
  const ingestUrl = 'http://localhost:4000/ingest/UserActivity';

  console.log('Reading CSV file...');
  const csvContent = fs.readFileSync(csvPath, 'utf8');
  const lines = csvContent.trim().split('\n');

  // Skip header row
  const dataLines = lines.slice(1);

  console.log(`Found ${dataLines.length} data rows to process`);

  let successCount = 0;
  let errorCount = 0;

  for (const line of dataLines) {
    if (line.trim() === '') continue;

    const [event_id, event_ts, user_id, action, duration_ms] = line.split(',');

    // Create the event object, ensuring duration_ms defaults to 0 if null/empty
    const event = {
      event_id: event_id.trim(),
      event_ts: event_ts.trim(),
      user_id: user_id.trim(),
      action: action.trim(),
      duration_ms: duration_ms && duration_ms.trim() !== '' ? parseFloat(duration_ms.trim()) : 0
    };

    try {
      console.log(`Posting event: ${event.event_id}`);
      const response = await fetch(ingestUrl, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(event)
      });

      if (response.ok) {
        console.log(`✓ Successfully posted ${event.event_id}`);
        successCount++;
      } else {
        console.error(`✗ Failed to post ${event.event_id}: ${response.status} ${response.statusText}`);
        const errorText = await response.text();
        console.error(`  Error details: ${errorText}`);
        errorCount++;
      }
    } catch (error) {
      console.error(`✗ Exception posting ${event.event_id}:`, error.message);
      errorCount++;
    }

    // Small delay to avoid overwhelming the API
    await new Promise(resolve => setTimeout(resolve, 100));
  }

  console.log(`\nData loading complete:`);
  console.log(`✓ Successful: ${successCount}`);
  console.log(`✗ Failed: ${errorCount}`);

  // Wait a moment for data to sync to ClickHouse, then check
  console.log('\nWaiting 3 seconds for data to sync to ClickHouse...');
  await new Promise(resolve => setTimeout(resolve, 3000));

  return { successCount, errorCount };
}

loadUserActivityData().catch(console.error);

