import { IngestPipeline, Api, sql } from "@514labs/moose-lib";

// User Activity Event Model
export interface UserActivity {
  event_id: string;
  event_ts: Date;
  user_id: string;
  action: string;
  duration_ms: number;
}

// Ingest Pipeline for User Activity Events
// Optimized for two query patterns:
// 1. Activity counts per user over a date range (user_id, event_ts ordering)
// 2. Total duration per action type (action included in ordering)
export const UserActivityPipeline = new IngestPipeline<UserActivity>(
  "UserActivity",
  {
    table: {
      orderByFields: ["user_id", "event_ts", "action"]
    },
    stream: true,
    ingestApi: true,
  }
);

// Analytics API 1: Activity counts per user over a date range
interface ActivityCountsInput {
  user_id?: string;
  start_date?: string;
  end_date?: string;
}

interface ActivityCountsRow {
  user_id: string;
  activity_count: number;
  date_range: string;
}

export const activityCountsPerUser = new Api<ActivityCountsInput, ActivityCountsRow>(
  "activity-counts-per-user",
  async ({ user_id, start_date = "2026-01-01", end_date = "2026-12-31" }, { client, sql }) => {
    const userFilter = user_id ? sql`AND user_id = ${user_id}` : sql``;

    const result = await client.query.execute(sql`
      SELECT
        user_id,
        count() AS activity_count,
        concat('${start_date}', ' to ', '${end_date}') AS date_range
      FROM UserActivity
      WHERE event_ts >= parseDateTimeBestEffort('${start_date}')
        AND event_ts <= parseDateTimeBestEffort('${end_date}')
        ${userFilter}
      GROUP BY user_id
      ORDER BY activity_count DESC
    `);

    return await result.json();
  }
);

// Analytics API 2: Total duration per action type
interface DurationByActionInput {
  action_type?: string;
}

interface DurationByActionRow {
  action: string;
  total_duration_ms: number;
  avg_duration_ms: number;
  event_count: number;
}

export const durationByActionType = new Api<DurationByActionInput, DurationByActionRow>(
  "duration-by-action-type",
  async ({ action_type }, { client, sql }) => {
    const actionFilter = action_type ? sql`WHERE action = ${action_type}` : sql``;

    const result = await client.query.execute(sql`
      SELECT
        action,
        sum(coalesce(duration_ms, 0)) AS total_duration_ms,
        avg(coalesce(duration_ms, 0)) AS avg_duration_ms,
        count() AS event_count
      FROM UserActivity
      ${actionFilter}
      GROUP BY action
      ORDER BY total_duration_ms DESC
    `);

    return await result.json();
  }
);

